{
  "doc_type": "Merkblatt",
  "audience": "Schülerinnen und Schüler der 2. Sekundarklassen",
  "core": {
    "what": {
      "text": "Die Schnupperwoche ist eine verpflichtende Schnupperlehre in einem Betrieb deiner Wahl für alle 2. Sekundarklassen vom 15. bis 19. März 2027.",
      "segment_ids": ["s0003"]
    },
    "must_do": {
      "text": "Du suchst dir selbst einen Schnupperplatz, gibst die Betriebsbestätigung bis 19. Februar 2027 deiner Klassenlehrperson ab und reichst den Schnupperbericht bis 2. April 2027 ein.",
      "segment_ids": ["s0007", "s0008", "s0021"]
    },
    "deadline": {
      "text": "Bestätigung bis 19. Februar 2027, Meldung bei fehlendem Platz bis 5. Februar 2027, Bericht bis 2. April 2027.",
      "segment_ids": ["s0008", "s0009", "s0021"]
    },
    "cost": {
      "text": "Verpflegung und Wegkosten gehen zulasten der Erziehungsberechtigten; die Schule erstattet bis zu 30 CHF pro Woche für öffentliche Verkehrsmittel.",
      "segment_ids": ["s0016", "s0017"]
    },
    "contact": {
      "text": "Klassenlehrperson, Schulsekretariat (Telefon 0441234570, E‑Mail sekretariat@sek-musterwil.example) und das Berufsinformationszentrum (BIZ), Bahnhofstrasse 10, 9999 Musterwil.",
      "segment_ids": ["s0010", "s0013", "s0023"]
    }
  },
  "facts": [
    {
      "id": "f01",
      "kind": "deadline",
      "text": "Die Bestätigung muss bis 19. Februar 2027 abgegeben werden.",
      "value_norm": "2027-02-19",
      "segment_ids": ["s0008"],
      "must_keep": true
    },
    {
      "id": "f02",
      "kind": "deadline",
      "text": "Fehlt bis 5. Februar 2027 ein Platz, muss man sich bei der Klassenlehrperson melden.",
      "value_norm": "2027-02-05",
      "segment_ids": ["s0009"],
      "must_keep": true
    },
    {
      "id": "f03",
      "kind": "deadline",
      "text": "Der Schnupperbericht ist bis spätestens 2. April 2027 einzureichen.",
      "value_norm": "2027-04-02",
      "segment_ids": ["s0021"],
      "must_keep": true
    },
    {
      "id": "f04",
      "kind": "amount",
      "text": "Die Schule erstattet höchstens 30 CHF pro Woche für Fahrten mit dem öffentlichen Verkehr.",
      "value_norm": "30",
      "segment_ids": ["s0017"],
      "must_keep": true
    },
    {
      "id": "f05",
      "kind": "obligation",
      "text": "Der Schüler muss den Schnupperplatz selbstständig suchen.",
      "value_norm": null,
      "segment_ids": ["s0007"],
      "must_keep": true
    },
    {
      "id": "f06",
      "kind": "obligation",
      "text": "Die vom Betrieb ausgefüllte Bestätigung ist der Klassenlehrperson zu geben.",
      "value_norm": null,
      "segment_ids": ["s0008"],
      "must_keep": true
    },
    {
      "id": "f07",
      "kind": "obligation",
      "text": "Bei Krankheit oder Unfall muss der Betrieb und das Schulsekretariat bis 7:30 Uhr informiert werden.",
      "value_norm": "07:30",
      "segment_ids": ["s0013"],
      "must_keep": true
    },
    {
      "id": "f08",
      "kind": "obligation",
      "text": "Bei mehr als 2 Tagen Absenzen ist ein Arztzeugnis nötig.",
      "value_norm": null,
      "segment_ids": ["s0014"],
      "must_keep": true
    },
    {
      "id": "f09",
      "kind": "right",
      "text": "Während der Schnupperlehre ist man über die Schule unfallversichert.",
      "value_norm": null,
      "segment_ids": ["s0018"],
      "must_keep": true
    },
    {
      "id": "f10",
      "kind": "condition",
      "text": "Kosten für Verpflegung und Arbeitsweg werden von den Erziehungsberechtigten getragen.",
      "value_norm": null,
      "segment_ids": ["s0016"],
      "must_keep": true
    },
    {
      "id": "f11",
      "kind": "contact",
      "text": "Das Berufsinformationszentrum (BIZ) befindet sich Bahnhofstrasse 10, 9999 Musterwil.",
      "value_norm": null,
      "segment_ids": ["s0010"],
      "must_keep": true
    },
    {
      "id": "f12",
      "kind": "contact",
      "text": "Telefon des Schulsekretariats: 0441234570.",
      "value_norm": "0441234570",
      "segment_ids": ["s0013"],
      "must_keep": true
    },
    {
      "id": "f13",
      "kind": "contact",
      "text": "E‑Mail des Schulsekretariats: sekretariat@sek-musterwil.example.",
      "value_norm": "sekretariat@sek-musterwil.example",
      "segment_ids": ["s0023"],
      "must_keep": true
    }
  ],
  "hard_terms": [
    {
      "term": "Schnupperwoche",
      "explanation": "Eine einwöchige Praxisphase, in der Schülerinnen und Schüler einen Betrieb kennenlernen.",
      "segment_ids": ["s0003"]
    },
    {
      "term": "Schnupperlehre",
      "explanation": "Ein kurzer Einblick in einen Beruf, der während der Schnupperwoche gemacht wird.",
      "segment_ids": ["s0004"]
    },
    {
      "term": "Berufsinformationszentrum (BIZ)",
      "explanation": "Eine Anlaufstelle, die bei der Berufswahl und der Suche nach einem Praktikumsplatz hilft.",
      "segment_ids": ["s0010"]
    },
    {
      "term": "Schulsekretariat",
      "explanation": "Das Büro der Schule, das administrative Aufgaben erledigt und als Kontakt dient.",
      "segment_ids": ["s0013", "s0023"]
    },
    {
      "term": "Schnuppertagebuch",
      "explanation": "Ein Heft, in dem die Schülerinnen und Schüler während der Schnupperwoche ihre Erlebnisse festhalten.",
      "segment_ids": ["s0020"]
    },
    {
      "term": "Haftpflichtversicherung",
      "explanation": "Versicherung, die Schäden abdeckt, die man anderen zufügt; hier Verantwortung der Eltern.",
      "segment_ids": ["s0019"]
    }
  ],
  "omit_candidates": [
    {
      "segment_ids": ["s0005"],
      "reason": "Verweis auf Lehrplan, für das Verständnis nicht nötig."
    },
    {
      "segment_ids": ["s0011"],
