    },
    {
      "segment_ids": ["s0019"],
      "reason": "Erwähnung der Haftpflichtversicherung der Eltern, nicht zentral für das Vorgehen."
    },
    {
      "segment_ids": ["s0025", "s0026", "s0027"],
      "reason": "Schlussformeln und Unterschrift, nicht inhaltlich relevant."
    }
  ]
}

